"""Original dementia chapter: clinical assessment and syndrome differentiation."""
from qbank_authoring import question,ref,finalize
NG=ref('NICE NG97 Dementia Recommendations','https://www.nice.org.uk/guidance/ng97/chapter/Recommendations')
DEL=ref('NICE CG103 Delirium Recommendations','https://www.nice.org.uk/guidance/cg103/chapter/Recommendations')
AA=ref('Alzheimer Association 2024 Revised Diagnostic and Staging Criteria','https://doi.org/10.1002/alz.13859')
EVAL=ref('Alzheimer Association Clinical Evaluation Guideline','https://www.alz.org/news/2024/clinical-practice-guideline-evaluation-alzheimers')
FT=ref('Rascovsky et al. Behavioral Variant FTD Criteria','https://pmc.ncbi.nlm.nih.gov/articles/PMC3170532/')
PPA=ref('Gorno-Tempini et al. Primary Progressive Aphasia Classification','https://pmc.ncbi.nlm.nih.gov/articles/PMC3059138/')
DLB=ref('DLB Consortium Fourth Consensus Report','https://pmc.ncbi.nlm.nih.gov/articles/PMC5496518/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('A patient has objective memory impairment but still independently manages medications, finances and travel using occasional reminders. Which distinction best separates mild cognitive impairment from dementia?', 'Preservation of functional independence despite cognitive decline',[
 ('An arbitrary screening score alone','Education, language and sensory impairment alter screening performance.'),('Complete absence of any memory complaint','MCI can involve both subjective and objective deficits.'),('Presence of any amyloid biomarker alone','A biological marker does not by itself define the degree of functional impairment.')],
 'Clinical stage depends on cognition and function', '**MCI permits independence, although tasks may require more effort or compensatory strategies.**', ['Establish a change from the individual baseline.','Use collateral history to assess real-world performance.'], '**Distinguish assistance from convenience.**', ['Family takeover without demonstrated inability can obscure staging.','Dementia involves cognitive decline that interferes with independent functioning.'], [['MCI','Independence largely retained'],['Dementia','Cognitive loss interferes with independence'],['Biomarker','Etiology, not functional stage alone']], [EVAL,AA], 'clinical_scenario')
q('An older patient with stable dementia becomes inattentive and disoriented over one day during pneumonia. What is the most appropriate working diagnosis?', 'Delirium superimposed on dementia',[
 ('Expected irreversible dementia progression over one day','The acute time course demands assessment of a superimposed process.'),('Primary psychosis based solely on disorientation','Inattention and systemic illness favor delirium.'),('Mild cognitive impairment','Established dementia and acute change are inconsistent with this label.')],
 'The time course identifies an acute brain disorder', '**Acute fluctuating attention or awareness change should trigger delirium assessment.**', ['Dementia increases vulnerability.','Hypoactive presentations can be mistaken for simple fatigue.'], '**Identify and treat contributing illness.**', ['Review infection, hypoxia, pain, retention and medicines.','When distinction is uncertain, prioritize delirium management.'], [['Dementia','Chronic baseline vulnerability'],['Delirium','Acute attention/awareness change'],['Both','Common coexistence']], [DEL], 'clinical_scenario')
q('Which history source is especially important when a patient minimizes progressive cognitive problems?', 'A reliable informant who can describe longitudinal cognitive and functional change',[
 ('A single self-rated memory score','Reduced insight can limit self-report.'),('A normal social greeting','Overlearned social behavior can remain intact despite impairment.'),('The age alone','Age changes probability but does not establish decline.')],
 'Collateral history supplies the trajectory', '**Anosognosia can make patient report incomplete.**', ['Ask about medication errors, financial mistakes, getting lost and behavior.','Clarify timing and the previous level of ability.'], '**Respect consent and autonomy during information gathering.**', ['Hear the patient’s priorities as well as family concerns.','Evaluate disagreement without assuming either account is complete.'], [['Patient account','Symptoms and priorities'],['Informant account','Observed change'],['Function','Determines practical consequences']], [EVAL])
q('A university graduate with progressive word-finding difficulty scores within the normal range on a brief global cognitive screen. What is the best next step?', 'Continue a focused cognitive-language and functional evaluation rather than excluding disease',[
 ('Exclude neurodegeneration because the total score is normal','Brief screens can miss focal or early syndromes.'),('Diagnose severe dementia from education alone','Education does not establish functional severity.'),('Repeat the identical screen indefinitely without domain testing','The presenting deficit requires more targeted assessment.')],
 'A screening result is not the whole diagnosis', '**Cognitive reserve and focal deficits can mask disease on a global score.**', ['Assess language, memory, executive and visuospatial domains as indicated.','Use neuropsychological evaluation when it will clarify the syndrome.'], '**Interpret performance in context.**', ['Language, education, hearing and vision influence testing.','Document everyday consequences and longitudinal change.'], [['Global screen','Initial estimate'],['Domain testing','Defines pattern'],['Collateral function','Establishes impact']], [EVAL,NG], 'clinical_scenario')
q('Which initial investigation strategy is most appropriate for progressive cognitive impairment?', 'A history-directed laboratory assessment and structural brain imaging, with further tests guided by the syndrome',[
 ('Amyloid PET before any history or examination','Specialized testing follows a clinical assessment and a defined question.'),('No evaluation because all cognitive decline is irreversible','Treatable contributors and structural mimics must be considered.'),('Routine brain biopsy in every patient','Biopsy is not a standard first-line dementia investigation.')],
 'Evaluate contributors as well as neurodegenerative causes', '**Medication effects, metabolic disorders and structural disease can alter cognition.**', ['Common laboratory assessment includes blood counts, metabolic measures, thyroid function and B12 according to context.','Additional infectious, autoimmune or nutritional tests depend on risk and phenotype.'], '**Use imaging to refine the differential.**', ['Look for vascular disease, hydrocephalus, masses and characteristic atrophy.','A scan alone rarely settles the full diagnosis.'], [['Laboratory work','Potential contributors'],['Structural imaging','Mimics and pattern'],['Advanced tests','Answer a focused uncertainty']], [EVAL,NG])
q('Progressive cognitive slowing is accompanied by neuropathy and macrocytosis. Which potentially treatable contributor deserves particular assessment?', 'Vitamin B12 deficiency',[
 ('A low serum sodium must be ignored if symptoms are chronic','Metabolic disturbances can contribute and need evaluation.'),('A positive amyloid scan excludes nutritional deficiency','Coexisting causes remain possible.'),('Normal hemoglobin always excludes neurological B12 deficiency','Neurological manifestations can occur without anemia.')],
 'Treatable contributors can coexist with degeneration', '**B12 deficiency can cause neurological and cognitive dysfunction.**', ['Interpret borderline levels with the clinical context and suitable confirmatory measures.','Absence of macrocytic anemia does not eliminate the diagnosis.'], '**Correct the deficiency without promising universal reversal.**', ['Longstanding injury may be incompletely reversible.','Continue evaluating other causes when the pattern or response warrants.'], [['B12 deficiency','Neurological and hematological effects'],['No anemia','Does not exclude'],['Replacement','Necessary, recovery variable']], [EVAL], 'clinical_scenario')
q('A patient taking oxybutynin, diphenhydramine and a sedative develops worsening cognition and falls. What management principle is most appropriate?', 'Review cumulative anticholinergic and sedative burden and deprescribe safely where feasible',[
 ('Add another sedative to improve all cognition','Additional sedation can worsen function and falls.'),('Attribute every symptom to Alzheimer disease without medication review','Medication effects may contribute substantially.'),('Stop all long-term sedatives abruptly regardless of dependence','Withdrawal can be dangerous; tapering may be needed.')],
 'Multiple modest drug effects can become a major cognitive burden', '**Central anticholinergic and sedative effects impair attention and function.**', ['Check prescribed and nonprescribed agents.','Balance urinary, sleep and psychiatric indications against cognitive harms.'], '**Make supervised, prioritized changes.**', ['Use safer alternatives where appropriate.','Reassess cognition and falls after modification.'], [['Anticholinergic load','Potential cognitive impairment'],['Sedation','Falls and impaired attention'],['Deprescribing','Individualized and supervised']], [NG], 'clinical_scenario')
q('Gradual early loss of episodic memory includes rapid forgetting despite cues, followed by impaired navigation and instrumental activities. Which syndrome is most typical?', 'Amnestic Alzheimer clinical syndrome',[
 ('Behavioral variant FTD with predominant early disinhibition','The dominant early deficit here is episodic memory.'),('Pure delirium','The insidious progressive course differs from an acute attention disorder.'),('Isolated primary progressive aphasia','Language is not the sole predominant early impairment.')],
 'Recognize an encoding and storage pattern', '**Typical amnestic AD presents with progressive episodic memory dysfunction.**', ['Repetition and missed recent events are common clues.','Other pathologies and mixed disease can mimic or modify the pattern.'], '**A clinical syndrome is not identical to a biological diagnosis.**', ['Biomarkers can clarify etiology when clinically indicated.','Functional assessment defines severity.'], [['Amnestic syndrome','Memory-led clinical pattern'],['AD biology','Requires appropriate etiological evidence'],['Stage','Determined clinically as well as biologically']], [AA,EVAL], 'clinical_scenario')
q('Under the Alzheimer Association 2024 framework, how should biological evidence of AD and clinical impairment be related?', 'They are related dimensions; biomarker evidence and the degree of clinical impairment should be described separately',[
 ('A positive biomarker automatically means severe dementia','Biological disease and functional stage are not synonymous.'),('Normal daily function makes all AD biomarkers impossible','Biological abnormalities can precede symptoms.'),('Clinical evaluation becomes unnecessary once any laboratory value is abnormal','Assay validity, context and alternative contributors remain essential.')],
 'State which diagnostic framework is being applied', '**The 2024 AA framework defines AD biologically using specified validated biomarkers.**', ['Clinical manifestations are staged separately.','Other expert frameworks differ in how asymptomatic positivity is labeled.'], '**Avoid overinterpreting an isolated test.**', ['Use validated assays in an appropriate population.','Biomarker positivity does not establish that every symptom is caused by AD.'], [['Biological dimension','Disease evidence'],['Clinical dimension','Symptoms and function'],['Interpretation','Framework and context matter']], [AA])
q('Which CSF pattern most supports Alzheimer pathology when measured with validated assays?', 'Reduced amyloid-beta 42/40 ratio with elevated phosphorylated tau',[
 ('High amyloid-beta 42/40 ratio with low phosphorylated tau as the classic pattern','This is the opposite of the usual supportive profile.'),('Isolated nonspecific total protein elevation','This does not establish AD pathology.'),('An isolated neutrophilic pleocytosis','This instead raises concern for another inflammatory or infectious process.')],
 'Use a disease-specific biomarker profile', '**Amyloid and tau measures inform the underlying pathological process.**', ['Ratio-based interpretation can reduce some sources of amyloid measurement variability.','Assay-specific cutoffs are essential.'], '**Do not replace the clinical differential with a biomarker panel.**', ['Mixed pathology remains possible.','Inflammatory CSF findings require separate evaluation.'], [['Amyloid ratio','Typically reduced'],['Phosphorylated tau','Typically elevated'],['Total protein alone','Nonspecific']], [AA])
q('An amyloid PET scan is positive in a patient with cognitive impairment. Which statement is most accurate?', 'It supports cerebral amyloid pathology but does not by itself establish symptom causality or clinical severity',[
 ('It distinguishes pure AD from every mixed pathology','Amyloid can coexist with other diseases.'),('It measures the patient’s decision-making capacity directly','Capacity requires a task-specific clinical assessment.'),('It predicts an exact remaining lifespan','Individual prognosis cannot be read from positivity alone.')],
 'An etiological marker has a defined scope', '**Amyloid positivity establishes a pathological component in the appropriate framework.**', ['Age, phenotype and other findings determine its clinical significance.','Tau and neurodegeneration measures answer partly different questions.'], '**Order advanced testing when it changes a decision.**', ['Treatment eligibility is one possible reason.','Explain the limits before testing.'], [['Amyloid PET','Amyloid pathology'],['Function','Clinical assessment'],['Mixed disease','Not excluded']], [AA])
q('A 58-year-old develops socially inappropriate behavior, loss of empathy, repetitive rituals and hyperorality before prominent memory complaints. Which syndrome is favored?', 'Behavioral variant frontotemporal dementia',[
 ('Typical amnestic Alzheimer syndrome','Memory-led decline is less consistent with the dominant early behavioral pattern.'),('Isolated semantic variant PPA','The central early deficit is not word meaning.'),('A single brief delirious episode','The progressive behavioral course is inconsistent with a transient acute state.')],
 'Early behavior can define the degenerative syndrome', '**Disinhibition, apathy, loss of empathy, stereotypy, hyperorality and executive dysfunction form the bvFTD feature set.**', ['The pattern must represent progressive change.','Probable criteria additionally require functional decline and supportive imaging.'], '**Exclude mimics and evaluate family history.**', ['Psychiatric disease can complicate recognition.','Genetic counseling may be relevant in selected families.'], [['bvFTD','Behavior-led decline'],['Probable syndrome','Function plus imaging support'],['Diagnosis','Requires exclusion of alternatives']], [FT], 'clinical_scenario')
q('Effortful halting speech with agrammatism and apraxia of speech dominates an insidious language disorder. Which PPA variant is most likely?', 'Nonfluent/agrammatic variant',[
 ('Semantic variant','Loss of word meaning and object knowledge is more characteristic.'),('Logopenic variant','Word retrieval and sentence repetition deficits without frank agrammatism are more typical.'),('Typical fluent Wernicke stroke aphasia','The gradual progression and effortful motor-language pattern differ.')],
 'Separate grammar and motor speech from semantics', '**Nonfluent/agrammatic PPA centers on agrammatism or effortful apraxic speech.**', ['Complex syntax comprehension may be impaired.','Single-word comprehension can be relatively preserved early.'], '**Phenotype predicts anatomy more reliably than exact pathology.**', ['Left posterior frontal-insular involvement is typical.','Clinical variants have imperfect pathological specificity.'], [['Nonfluent','Grammar/motor speech'],['Semantic','Word meaning'],['Logopenic','Retrieval and repetition']], [PPA], 'clinical_scenario')
q('Fluent grammatical speech is accompanied by profound loss of single-word comprehension and object knowledge, with relatively preserved repetition. Which PPA variant fits?', 'Semantic variant',[
 ('Nonfluent/agrammatic variant','Effortful agrammatic output is not the dominant finding.'),('Logopenic variant','Sentence repetition impairment is a major feature there.'),('Pure dysarthria','An articulation disorder does not explain loss of word meaning.')],
 'Semantic knowledge is the central deficit', '**Anomia and impaired single-word comprehension define the semantic variant.**', ['Object knowledge can decline across modalities.','Surface dyslexia or dysgraphia may occur.'], '**Assess the anterior temporal pattern.**', ['Atrophy often predominates in anterior temporal regions.','Preserved repetition does not imply preserved comprehension.'], [['Meaning','Markedly impaired'],['Repetition','Relatively spared early'],['Speech form','Often fluent and grammatical']], [PPA], 'clinical_scenario')
q('Word-finding pauses and impaired sentence repetition occur with preserved grammar and single-word meaning. Which PPA variant is most likely?', 'Logopenic variant',[
 ('Semantic variant','Word meaning is relatively preserved here.'),('Nonfluent/agrammatic variant','Frank agrammatism or apraxic effortful speech is not described.'),('Pure motor dysarthria','This cannot explain phonological working-memory and repetition deficits.')],
 'A phonological working-memory phenotype guides classification', '**Logopenic PPA features word retrieval and phrase/sentence repetition difficulty.**', ['Phonological errors can occur.','Left temporoparietal involvement is characteristic.'], '**Consider AD as a common underlying substrate.**', ['The phenotype is not equivalent to pathological proof.','Use etiological biomarkers when clinically useful.'], [['Retrieval','Impaired'],['Sentence repetition','Impaired'],['Grammar/word meaning','Relatively preserved early']], [PPA], 'clinical_scenario')
q('Which cluster comprises core clinical features of dementia with Lewy bodies?', 'Fluctuating cognition, recurrent formed visual hallucinations, REM sleep behavior disorder and spontaneous parkinsonism',[
 ('Early amnesia, hyperorality, isolated dysarthria and peripheral neuropathy','This is not the defined core feature cluster.'),('Vertical gaze palsy, alien limb, sensory ataxia and areflexia','These suggest other neurological syndromes.'),('Orthostatic hypotension alone without dementia','Autonomic dysfunction is supportive but does not replace the dementia requirement.')],
 'Combine core features with the dementia syndrome', '**DLB commonly affects attention, executive and visuoperceptual function.**', ['Marked memory impairment need not dominate at onset.','Indicative biomarkers have specified roles in probable and possible criteria.'], '**Recognize management consequences.**', ['Assess falls, autonomic dysfunction and sleep safety.','Use particular caution with dopamine-blocking antipsychotics.'], [['Core phenotype','Fluctuation, hallucinations, RBD, parkinsonism'],['Cognition','Often executive/visuospatial'],['Safety','Medication sensitivity']], [DLB])
q('A patient with probable DLB develops severe rigidity, sedation and reduced responsiveness after haloperidol. What is the most likely explanation?', 'Severe neuroleptic sensitivity associated with Lewy body disease',[
 ('Proof that the original diagnosis must have been pure AD','The reaction is a recognized DLB concern.'),('A therapeutic response that should be intensified','The deterioration warrants urgent reassessment and drug review.'),('Expected benign sleep restoration alone','Marked motor and awareness changes are not a benign target response.')],
 'Antipsychotic risk depends on the disease substrate', '**Potent dopamine blockade can produce pronounced deterioration in DLB.**', ['Assess urgently for severe adverse reactions and other acute causes.','Nonpharmacological and reversible-cause approaches come first where feasible.'], '**If medication is essential, seek a specialist strategy.**', ['Use the lowest appropriate exposure and monitor closely.','Explain the risk-benefit decision to caregivers.'], [['Potent D2 blockade','High concern in DLB'],['Acute deterioration','Urgent reassessment'],['Treatment decision','Specialist risk-benefit balance']], [DLB], 'clinical_scenario')
q('Executive slowing and gait dysfunction follow multiple strokes, but memory decline is also progressive between events. Which conclusion is most appropriate?', 'Vascular cognitive impairment with possible coexisting neurodegenerative pathology',[
 ('All vascular cognitive disease must decline in a perfectly stepwise fashion','Subcortical small-vessel disease can produce gradual decline.'),('Amyloid pathology is impossible after stroke','Mixed vascular and degenerative pathology is common.'),('Any white-matter lesion proves pure vascular dementia','Imaging changes require clinical correlation.')],
 'Vascular cognitive impairment has several trajectories', '**Strategic infarcts, multiple lesions and small-vessel disease can affect cognition differently.**', ['Executive dysfunction and slowed processing can be prominent.','Stroke chronology and lesion location strengthen causal attribution.'], '**Address modifiable vascular risks.**', ['Consider mixed disease when the phenotype suggests it.','Imaging burden alone does not determine cognitive causality.'], [['Large/strategic infarct','Possible abrupt decline'],['Small-vessel disease','Often executive slowing'],['Mixed disease','Common possibility']], [EVAL,NG], 'clinical_scenario')

